from typing import List

def validateBinaryTreeNodes(n: int, leftChild: List[int], rightChild: List[int]) -> bool:
    # Step 1: Count the in-degrees of each node
    in_degree = [0] * n
    for i in range(n):
        if leftChild[i] != -1:
            in_degree[leftChild[i]] += 1
        if rightChild[i] != -1:
            in_degree[rightChild[i]] += 1

    # Step 2: Find the root(s)
    roots = [i for i in range(n) if in_degree[i] == 0]

    # There must be exactly one root
    if len(roots) != 1:
        return False

    # Step 3: Check if the tree is acyclic and connected
    visited = [False] * n
    stack = [roots[0]]

    while stack:
        node = stack.pop()
        if visited[node]:
            return False
        visited[node] = True
        if leftChild[node] != -1:
            stack.append(leftChild[node])
        if rightChild[node] != -1:
            stack.append(rightChild[node])

    # The tree is connected if all nodes are visited
    return sum(visited) == n
